// Ported from the public AIcss React source.
// Source: https://www.aicss.dev/components/streaming-text
"use client"

import styles from "./aicss-streaming-text.module.css";
import { useEffect, useState } from "react";

export function StreamingText({ text }: { text: string }) {
  const [shown, setShown] = useState("");
  useEffect(() => {
    let i = 0;
    const id = setInterval(() => {
      i += 2;
      setShown(text.slice(0, i));
      if (i >= text.length) clearInterval(id);
    }, 9);
    return () => clearInterval(id);
  }, [text]);
  const streaming = shown.length < text.length;
  return (
    <p className={styles.prose}>
      {shown}
      <span className={streaming ? styles.caret + " " + styles.caretSteady : styles.caret} />
    </p>
  );
}

export { StreamingText as AiCssStreamingText }

/* Ported from https://www.aicss.dev/components/streaming-text */
.prose { font-size: 0.875rem; line-height: 1.1875rem; color: var(--foreground); }
.caret { display: inline-block; width: 0.5rem; height: 1.05em; margin-left: 0.125rem; background: var(--foreground); vertical-align: text-bottom; animation: caret-blink 1s step-end infinite; }
/* solid while streaming, blink only once idle (matches the live component) */
.caretSteady { animation: none; opacity: 1; }
@keyframes caret-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .caret { animation: none; } }
@media (prefers-reduced-motion: reduce) {
 .caret,
.caretSteady { animation: none !important; transition-duration: 0.01ms !important; } }
